const msg = $json.data.messages;
const audio = msg.message.audioMessage;

if (!audio) {
  throw new Error("No audio message found");
}

return [{
  json: {
    decryptPayload: {
      data: {
        messages: {
          key: {
            id: msg.key.id
          },
          message: {
            audioMessage: {
              url: audio.url,
              mimetype: audio.mimetype,
              mediaKey: audio.mediaKey,
              fileSha256: audio.fileSha256,
              fileLength: audio.fileLength
            }
          }
        }
      }
    }
  }
}];

const msg = $json.data.messages;
const image = msg.message.imageMessage;

if (!image) {
  throw new Error("No image message found");
}

return [{
  json: {
    decryptPayload: {
      data: {
        messages: {
          key: {
            id: msg.key.id
          },
          message: {
            imageMessage: {
              url: image.url,
              mimetype: image.mimetype,
              mediaKey: image.mediaKey,
              fileSha256: image.fileSha256,
              fileLength: image.fileLength,
              fileName: image.fileName || "image.jpg"
            }
          }
        }
      }
    }
  }
}];

const items = $input.all();

// ---- 1. Extract the message text from whichever branch fired (text / transcribed audio / analyzed image) ----
function extractTextDeeply(obj) {
  if (!obj || typeof obj !== "object") return null;

  // Explicit fast-path: OpenAI Responses API message shape
  // { id, type: "message", status, content: [{ type: "output_text", text, ... }], role }
  if (obj.type === "message" && Array.isArray(obj.content)) {
    for (const part of obj.content) {
      if (
        part &&
        part.type === "output_text" &&
        typeof part.text === "string" &&
        part.text.trim()
      ) {
        return part.text.trim();
      }
    }
  }

  if (typeof obj.messageBody === "string" && obj.messageBody.trim()) return obj.messageBody.trim();
  if (typeof obj.conversation === "string" && obj.conversation.trim()) return obj.conversation.trim();
  if (typeof obj.text === "string" && obj.text.trim()) return obj.text.trim();
  if (typeof obj.caption === "string" && obj.caption.trim()) return obj.caption.trim();

  if (Array.isArray(obj)) {
    for (const el of obj) {
      const found = extractTextDeeply(el);
      if (found) return found;
    }
    return null;
  }

  for (const key in obj) {
    const found = extractTextDeeply(obj[key]);
    if (found) return found;
  }
  return null;
}

let finalMessage = "";
for (const item of items) {
  const found = extractTextDeeply(item.json);
  if (found) { finalMessage = found; break; }
}

// ---- 2. Resolve the sender's real phone number from the ORIGINAL webhook payload ----
// IMPORTANT: the audio and image branches (Code in JavaScript / Code in JavaScript1)
// strip the payload down to only { key: { id }, message: { audioMessage/imageMessage } }
// before calling the decrypt-media endpoint, because that's all that endpoint needs.
// That means key.cleanedSenderPn / remoteJid / senderLid never survive in the main
// data path for those two branches by the time execution reaches this node.
// Fix: read sender identity straight from the WasenderAPI Trigger node itself via a
// node reference. This is a stable, direct link to the original webhook payload and
// works identically no matter which branch (text/audio/image) actually fired, so we
// don't need to thread sender fields through every intermediate HTTP/OpenAI node.
let triggerJson = {};
try {
  triggerJson = $('WasenderAPI Trigger').first().json || {};
} catch (e) {
  triggerJson = {};
}

const key = (triggerJson.data && triggerJson.data.messages && triggerJson.data.messages.key) || {};

// A raw WhatsApp JID is "<id>@<domain>". The domain tells you what kind of id it is:
//   @s.whatsapp.net / @c.us  -> id IS the real phone number (MSISDN)
//   @lid                     -> id is an opaque "Linked ID", NOT a phone number
//                                (WhatsApp's privacy layer for business/bot integrations)
//   @g.us                    -> id is a group, not a person
function classifyJid(raw) {
  if (typeof raw !== "string" || !raw.trim()) return null;
  const trimmed = raw.trim();
  const atIndex = trimmed.indexOf("@");
  if (atIndex === -1) return { id: trimmed, type: "phone" };
  const id = trimmed.slice(0, atIndex);
  const domain = trimmed.slice(atIndex + 1);
  let type = "unknown";
  if (domain === "s.whatsapp.net" || domain === "c.us") type = "phone";
  else if (domain === "lid") type = "lid";
  else if (domain === "g.us") type = "group";
  return { id, type };
}

// WasenderAPI's own docs: "Do not rely on remoteJid to be a phone number. It can
// often be a LID. Always use the cleaned fields if you need the specific phone
// number." cleanedSenderPn is the resolved MSISDN for private chats;
// cleanedParticipantPn is the equivalent for the actual sender inside a group chat.
let senderDigits = "";
let senderIdType = "unknown";

if (typeof key.cleanedSenderPn === "string" && key.cleanedSenderPn.trim()) {
  senderDigits = key.cleanedSenderPn.trim();
  senderIdType = "phone";
} else if (typeof key.cleanedParticipantPn === "string" && key.cleanedParticipantPn.trim()) {
  senderDigits = key.cleanedParticipantPn.trim();
  senderIdType = "phone";
} else {
  const resolved = classifyJid(key.remoteJid) || classifyJid(key.senderLid);
  if (resolved) {
    senderDigits = resolved.id;
    senderIdType = resolved.type;
  }
}

// Strip any stray "+" the source might already include, then apply exactly one,
// so this is ready to drop straight into WasenderAPI's "to" field (E.164 format).
const senderNumber = senderDigits ? "+" + senderDigits.replace(/^\+/, "") : "";

return [
  {
    json: {
      userMessage: finalMessage || "",
      senderNumber,
      // "phone" = real MSISDN, safe to send to directly.
      // "lid"/"group"/"unknown" = the resolver couldn't get a cleaned phone number
      // (this should be rare in practice since cleanedSenderPn is checked first).
      senderIdType
    }
  }
];

const agentOutput = $input.first().json.output;

return [
  {
    json: {
      replyText: agentOutput.replyText,
      orderConfirmed: agentOutput.orderConfirmed === true
    }
  }
];

const orderId = `AWS-${Date.now()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;
const approvalToken = Math.random().toString(36).substring(2, 10);

return [
  {
    json: {
      ...$input.first().json,
      orderId: orderId,
      approvalToken: approvalToken
    }
  }
];

// Idempotency guard. WhatsApp bridges redeliver webhooks on timeout/retry.
// Without this, one customer message can create TWO order rows and TWO
// approval emails -> real money lost. Keyed on the immutable WhatsApp
// message id (data.messages.key.id).
//
// Best-effort: uses workflow static data (persisted per workflow). Under
// heavy concurrency there is a small race window; Redis SETNX is the
// bulletproof version if/when you add a Redis credential.
const root = $input.first()?.json || {};
const msgId = root?.data?.messages?.key?.id || null;

if (!msgId) {
  // No id to dedupe on — let it through rather than silently dropping orders.
  return [{ json: { ...root, _dedupe: 'no-id' } }];
}

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seenIds)) store.seenIds = [];

if (store.seenIds.includes(msgId)) {
  return []; // duplicate -> stop this execution branch dead
}

store.seenIds.push(msgId);
// Bounded ring buffer so static data can't grow without limit.
if (store.seenIds.length > 500) {
  store.seenIds = store.seenIds.slice(-500);
}

return [{ json: { ...root, _dedupe: 'first-seen' } }];

// Compute a human-plausible reply delay in SECONDS.
//
// WHY NOT A FIXED WAIT: a constant interval is a machine signature. Real
// people vary. Randomized, length-proportional jitter is simultaneously
// faster (avg ~2-4s vs a flat 10s) and less bot-like than any fixed value.
//
// Kept strictly under 65s so n8n does NOT offload the execution to the
// database and reload it — that keeps latency low and DB churn near zero.
const reply = String($json.replyText || "");
const chars = reply.length;

// ~22 chars/sec composing speed, capped so a long menu dump doesn't stall.
const typing = Math.min(chars / 22, 4.0);
// 0.4-1.6s of natural variance.
const jitter = Math.random() * 1.2 + 0.4;

let delaySeconds = Math.round((typing + jitter) * 10) / 10;
if (delaySeconds < 0.8) delaySeconds = 0.8;
if (delaySeconds > 6) delaySeconds = 6;

return [{ json: { ...$json, delaySeconds } }];
